-- HemoCura Training Native 1.1 controlled content seed.
-- Content remains DRAFT/BORRADOR until formal document approval.

update public.training_content_versions v set controlled_document_id=d.id
from public.document_register d where v.version_code='TRN-1.0-RC' and d.document_code='HC-TRN-SUITE-001';

