insert into public.training_programs(program_code,training_id,competency_id,content_version_id,title,audience_label,pass_threshold,critical_process,estimated_minutes,modules,practices,microlearning)
select s.program_code,t.id,c.id,v.id,s.title,s.audience,s.threshold,s.critical,s.minutes,s.modules,s.practices,s.micro
from src s join public.training_events t on t.training_code=s.training_code join public.competency_catalog c on c.competency_code=s.competency_code join public.training_content_versions v on v.version_code='TRN-1.0-RC'
on conflict(program_code) do update set training_id=excluded.training_id,competency_id=excluded.competency_id,content_version_id=excluded.content_version_id,title=excluded.title,audience_label=excluded.audience_label,pass_threshold=excluded.pass_threshold,critical_process=excluded.critical_process,estimated_minutes=excluded.estimated_minutes,modules=excluded.modules,practices=excluded.practices,microlearning=excluded.microlearning,updated_at=now(),active=true;

with m(program_code,role_code) as (values
('TRN-AO','ASISTENTE_OPERACIONES'),('TRN-EL','ENCARGADA_LABORATORIO'),('TRN-EL','LABORATORIO'),('TRN-MGT','MEDICO_GERENTE_TECNICO'),('TRN-QMS','CALIDAD'),('TRN-SU','SUPER_USUARIO'),('TRN-SU','ADMIN'),('TRN-GER','GERENCIA_OPERATIVA'),('TRN-GER','GERENCIA_GENERAL'),('TRN-GER','SOCIO'),('TRN-TI','TI'))
insert into public.training_program_job_roles(program_id,job_role_id)
select p.id,j.id from m join public.training_programs p on p.program_code=m.program_code join public.job_roles j on j.role_code=m.role_code
on conflict do nothing;

