insert into public.training_question_bank(program_id,question_code,prompt,options,correct_index,explanation,difficulty)
select p.id,q.question_code,q.prompt,q.options,q.correct_index,q.explanation,q.difficulty from q join public.training_programs p on p.program_code=q.program_code
on conflict(program_id,question_code) do update set prompt=excluded.prompt,options=excluded.options,correct_index=excluded.correct_index,explanation=excluded.explanation,difficulty=excluded.difficulty,active=true;

insert into public.training_knowledge_snippets(document_id,role_scope,keywords,answer)
select d.id,x.role_scope,x.keywords,x.answer from public.document_register d cross join (values
('{}'::text[],array['reporte','diario'], 'Confirma fecha, sucursal y responsable; registra lotes, inventario y despachos; valida balances. Guardar, enviar a revisión y cerrar son acciones distintas.'),
('{}'::text[],array['permission','denied'], 'Conserva el mensaje exacto, usuario, rol, sucursal, módulo, acción y hora. Revisa autenticación, permiso, alcance de sucursal, RLS y RPC. No amplíes privilegios como atajo.'),
(array['ASISTENTE_OPERACIONES']::text[],array['diferido','donante'], 'DIFERIDO exige motivo documentado. La Suite organiza el registro, pero la elegibilidad depende de revisión humana autorizada.'),
(array['ENCARGADA_LABORATORIO','MEDICO_GERENTE_TECNICO']::text[],array['tamizaje','resultado'], 'Cada prueba y resultado debe seleccionarse explícitamente. El registro no equivale a liberación clínica automática.'),
(array['ENCARGADA_LABORATORIO','MEDICO_GERENTE_TECNICO']::text[],array['cadena','frío'], 'Detecta, documenta, contiene y escala según el procedimiento. La disponibilidad en inventario no sustituye la evaluación de una excursión térmica.'),
('{}'::text[],array['certificado','vigencia'], 'La constancia oficial requiere evaluación aprobada, práctica supervisada, instructor autorizado y segregación participante/evaluador.')) as x(role_scope,keywords,answer)
where d.document_code='HC-TRN-SUITE-001'
and not exists(select 1 from public.training_knowledge_snippets k where k.document_id=d.id and k.keywords=x.keywords);
